SELECT CASE WHEN budget >= 3209000 THEN 'high' WHEN budget >= 1276000 THEN 'mid' ELSE 'low' END budget_bucket, location, COUNT(DISTINCT budget) unique_dept_names, COUNT(DISTINCT budget) unique_locations FROM departments WHERE budget <= 1718000 AND budget > 2265000 GROUP BY CASE WHEN budget >= 3209000 THEN 'high' WHEN budget >= 1276000 THEN 'mid' ELSE 'low' END, location HAVING COUNT(DISTINCT budget) >= 3 ORDER BY budget_bucket, unique_dept_names;
